#define MAX_PARTICLES 128
#define PARTICLE_TYPES 4
#define SMOOTHING_FACTOR 0.14
// Particle appearance parameters
#define BASE_PARTICLE_SIZE 0.12    // Base size of particles
#define SIZE_VARIATION 0.05        // How much size varies between types
#define PULSE_AMPLITUDE 0.02       // How much size pulses
#define GLOW_INTENSITY 0.4         // Intensity of particle glow

float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}
float getParticleSize(float type, float time) {
    // Base size varies by type
    float size = BASE_PARTICLE_SIZE + SIZE_VARIATION * (type / float(PARTICLE_TYPES));

    // Add pulsing effect
    size += PULSE_AMPLITUDE * sin(time * 2.0 + type * 2.0);

    return size;
}
float particleSDF(vec3 p, vec3 center, float size) {
    return length(p - center) - size;
}
float sceneSDF(vec3 p) {
    float d = 1000.0;

    for (int i = 0; i < MAX_PARTICLES; i++) {
        vec4 particle = texelFetch(iChannel0, ivec2(i, 0), 0);
        float size = getParticleSize(particle.w, iTime);
        float particleD = particleSDF(p, particle.xyz, size);
        d = smin(d, particleD, SMOOTHING_FACTOR);
    }

    return d;
}
float raymarch(vec3 ro, vec3 rd) {
    float t = 0.0;

    for (int i = 0; i < 38; i++) {
        vec3 p = ro + rd * t;
        float d = sceneSDF(p);

        if (d < 0.01) break;
        if (t > 20.0) break;

        t += d * 0.5;
    }

    return t;
}
vec3 calcNormal(vec3 p) {
    const float h = 0.001;
    const vec2 k = vec2(1.0, -1.0);
    return normalize(
        k.xyy * sceneSDF(p + k.xyy * h) +
        k.yyx * sceneSDF(p + k.yyx * h) +
        k.yxy * sceneSDF(p + k.yxy * h) +
        k.xxx * sceneSDF(p + k.xxx * h)
    );
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Animated camera
    float camRadius = 8.0 + sin(iTime * 0.1) * 1.0;
    float camAngle = iTime * 0.2;
    vec3 ro = vec3(cos(camAngle) * camRadius, 2.0 + sin(iTime * 0.15) * 1.0, sin(camAngle) * camRadius);
    vec3 lookAt = vec3(0.0, 0.0, 0.0);

    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = cross(right, forward);
    vec3 rd = normalize(forward + right * uv.x + up * uv.y);

    float t = raymarch(ro, rd);

    vec3 col = vec3(0.0);
    if (t < 20.0) {
        vec3 p = ro + rd * t;
        vec3 n = calcNormal(p);

        vec3 light = normalize(vec3(1.0, 1.0, -1.0));
        float diff = max(0.0, dot(n, light));
        float amb = 0.2;

        float minDist = 1000.0;
        int nearestType = 0;
        for (int i = 0; i < MAX_PARTICLES; i++) {
            vec4 particle = texelFetch(iChannel0, ivec2(i, 0), 0);
            float dist = length(p - particle.xyz);
            if (dist < minDist) {
                minDist = dist;
                nearestType = int(particle.w);
            }
        }

        vec3 typeColors[PARTICLE_TYPES] = vec3[](
            vec3(1.0, 0.2, 0.2),
            vec3(0.2, 1.0, 0.2),
            vec3(0.2, 0.2, 1.0),
            vec3(1.0, 1.0, 0.2)
        );

        vec3 baseColor = typeColors[nearestType];

        // Add glow
        float glow = exp(-minDist * 2.0) * GLOW_INTENSITY;
        col = baseColor * (diff + amb) + baseColor * glow;
    }

    // Add some post-processing
    col = pow(col, vec3(0.8)); // Gamma correction
    col += vec3(0.1, 0.1, 0.2) * length(uv); // Subtle vignette

    fragColor = vec4(col, 1.0);
}

// Buffer A: Particle Positions
#define MAX_PARTICLES 128
#define PARTICLE_TYPES 4

// Space parameters
#define SPACE_SIZE_X 16.0
#define SPACE_SIZE_Y 20.0
#define SPACE_SIZE_Z 10.0

// Spawn parameters
#define SPAWN_CENTER_X 0.0      
#define SPAWN_CENTER_Y 0.0      
#define SPAWN_CENTER_Z 0.0      
#define SPAWN_WIDTH 8.0        
#define SPAWN_HEIGHT 8.0       
#define SPAWN_DEPTH 8.0         

// Utility functions
float hash11(float p) {
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

vec3 hash31(float p) {
    vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xxy + p3.yzz) * p3.zyx);
}

// Wrap position in toroidal space
vec3 wrapPosition(vec3 pos) {
    vec3 spaceSize = vec3(SPACE_SIZE_X, SPACE_SIZE_Y, SPACE_SIZE_Z);
    vec3 halfSize = spaceSize * 0.5;

    vec3 wrapped = pos;
    wrapped.x = pos.x + halfSize.x;
    wrapped.x = mod(wrapped.x, spaceSize.x);
    wrapped.x = wrapped.x - halfSize.x;

    wrapped.y = pos.y + halfSize.y;
    wrapped.y = mod(wrapped.y, spaceSize.y);
    wrapped.y = wrapped.y - halfSize.y;

    wrapped.z = pos.z + halfSize.z;
    wrapped.z = mod(wrapped.z, spaceSize.z);
    wrapped.z = wrapped.z - halfSize.z;

    return wrapped;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 pixel = ivec2(fragCoord);

    if (pixel.y != 0 || pixel.x >= MAX_PARTICLES) {
        fragColor = vec4(0.0);
        return;
    }

    // Get current particle state
    vec4 particle = texelFetch(iChannel0, pixel, 0);
    vec4 velocity = texelFetch(iChannel1, pixel, 0);

    // On first frame, initialize particles in visible area
    if (iFrame == 0) {
        // Generate random position in spawn zone
        vec3 rand = hash31(float(pixel.x));

        vec3 spawnPos;
        spawnPos.x = SPAWN_CENTER_X + (rand.x * 2.0 - 1.0) * (SPAWN_WIDTH * 0.5);
        spawnPos.y = SPAWN_CENTER_Y + (rand.y * 2.0 - 1.0) * (SPAWN_HEIGHT * 0.5);
        spawnPos.z = SPAWN_CENTER_Z + (rand.z * 2.0 - 1.0) * (SPAWN_DEPTH * 0.5);

        // Distribute types evenly
        float type = floor(hash11(float(pixel.x) * 123.456) * float(PARTICLE_TYPES));

        fragColor = vec4(spawnPos, type);
        return;
    }

    // Update position
    vec3 newPos = particle.xyz + velocity.xyz * 0.016;

    // Wrap position in toroidal space
    newPos = wrapPosition(newPos);

    fragColor = vec4(newPos, particle.w);
}

// Buffer B: Particle Velocities
#define MAX_PARTICLES 128
#define PARTICLE_TYPES 4

// Space parameters (must match Buffer A)
#define SPACE_SIZE_X 16.0       
#define SPACE_SIZE_Y 20.0       
#define SPACE_SIZE_Z 10.0       

// Interaction parameters
#define MAX_ATTRACTION_DIST 2.0
#define MIN_REPULSION_DIST 0.5
#define COLLISION_DIST 0.6
#define REPULSION_STRENGTH 14.0

// Dynamic parameters
#define TIME_SCALE 0.4
#define VELOCITY_PERSISTENCE 1.
#define FORCE_SCALE 0.05
#define CHAOS_AMPLITUDE 0.1
#define FLOW_STRENGTH 0.1

// Calculate shortest distance in toroidal space
vec3 toroidalDifference(vec3 pos1, vec3 pos2) {
    vec3 spaceSize = vec3(SPACE_SIZE_X, SPACE_SIZE_Y, SPACE_SIZE_Z);
    vec3 diff = pos2 - pos1;

    // For each dimension, check if going through the wrap is shorter
    for (int i = 0; i < 3; i++) {
        if (diff[i] > spaceSize[i] * 0.5) {
            diff[i] -= spaceSize[i];
        } else if (diff[i] < -spaceSize[i] * 0.5) {
            diff[i] += spaceSize[i];
        }
    }

    return diff;
}

const float attractionMatrix[PARTICLE_TYPES * PARTICLE_TYPES] = float[](
    // Type 0  Type 1  Type 2  Type 3
     13.0,    -13.5,    4.2,    5.2,    // Type 0
    -9.5,     21.0,   -10.2,    15.4,    // Type 1
     23.2,    -11.2,    46.0,   -22.3,    // Type 2
     13.3,     18.4,   -14.3,    19.4     // Type 3
);

// Flow field noise
float hash12(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 flowField(vec3 pos, float time) {
    float noiseScale = 0.5;
    vec2 flow = vec2(
        hash12(vec2(floor(pos.xz * noiseScale + time))),
        hash12(vec2(floor(pos.xz * noiseScale - time)))
    ) * 2.0 - 1.0;
    return flow;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 pixel = ivec2(fragCoord);

    if (pixel.y != 0 || pixel.x >= MAX_PARTICLES) {
        fragColor = vec4(0.0);
        return;
    }

    // Get current particle state
    vec4 particle = texelFetch(iChannel0, pixel, 0);
    vec4 velocity = texelFetch(iChannel1, pixel, 0);

    if (iFrame == 0) {
        fragColor = vec4(0.0);
        return;
    }

    vec3 force = vec3(0.0);
    vec3 repulsionForce = vec3(0.0);

    // Time-varying parameters
    float timeScale = TIME_SCALE * (1.0 + 0.2 * sin(iTime * 0.1)); // Fluctuating time scale

    // Calculate forces from other particles
    for (int i = 0; i < MAX_PARTICLES; i++) {
        if (i == pixel.x) continue;

        vec4 otherParticle = texelFetch(iChannel0, ivec2(i, 0), 0);
        vec3 diff = toroidalDifference(particle.xyz, otherParticle.xyz);
        float dist = length(diff);

        if (dist < COLLISION_DIST) {
            float repulsionFactor = 1.0 - (dist / COLLISION_DIST);
            repulsionForce -= normalize(diff) * repulsionFactor * REPULSION_STRENGTH;
            continue;
        }

        if (dist > MAX_ATTRACTION_DIST) continue;

        int type1 = int(particle.w);
        int type2 = int(otherParticle.w);
        float attraction = attractionMatrix[type1 * PARTICLE_TYPES + type2];

        // Add time variation to force
        float timeFactor = 1.0 + 0.2 * sin(iTime * 0.5 + float(type1 + type2));
        float forceMag = attraction * timeFactor * (1.0 - smoothstep(MIN_REPULSION_DIST, MAX_ATTRACTION_DIST, dist));
        force += normalize(diff) * forceMag;
    }

    // Add flow field influence
    vec2 flow = flowField(particle.xyz, iTime * 0.1);
    force.xz += flow * FLOW_STRENGTH;

    // Add some chaos
    vec3 chaos = vec3(
        hash12(vec2(iTime, pixel.x)),
        hash12(vec2(iTime + 1.0, pixel.x)),
        hash12(vec2(iTime + 2.0, pixel.x))
    ) * 2.0 - 1.0;
    force += chaos * CHAOS_AMPLITUDE;

    // Combine forces
    force += repulsionForce;

    // Update velocity with varying parameters
    vec3 newVel = velocity.xyz * VELOCITY_PERSISTENCE + force * FORCE_SCALE * timeScale;

    // Limit maximum velocity
    float maxSpeed = 2.0 + sin(iTime * 0.2) * 0.5; // Varying speed limit
    float speed = length(newVel);
    if (speed > maxSpeed) {
        newVel = (newVel / speed) * maxSpeed;
    }

    fragColor = vec4(newVel, 0.0);
}
